function getContext(canvas) {
  const context = canvas.getContext("2d");
  context.imageSmoothingEnabled = true;
  context.imageSmoothingQuality = "high";
  return context;
}

function coverImage(context, image, x = 0, y = 0, width = SIZE, height = SIZE) {
  const scale = Math.max(width / image.naturalWidth, height / image.naturalHeight);
  const sourceWidth = width / scale;
  const sourceHeight = height / scale;
  const sourceX = (image.naturalWidth - sourceWidth) * state.photoPosition.x;
  const sourceY = (image.naturalHeight - sourceHeight) * state.photoPosition.y;
  context.drawImage(image, sourceX, sourceY, sourceWidth, sourceHeight, x, y, width, height);
}

function containImage(context, image, x, y, width, height) {
  const scale = Math.min(width / image.naturalWidth, height / image.naturalHeight);
  const drawWidth = image.naturalWidth * scale;
  const drawHeight = image.naturalHeight * scale;
  context.drawImage(image, x + (width - drawWidth) / 2, y + (height - drawHeight) / 2, drawWidth, drawHeight);
}

function getImageDimensions(image) {
  return {
    width: image.naturalWidth || image.width,
    height: image.naturalHeight || image.height
  };
}

const logoBoundsCache = new WeakMap();

function getLogoBounds(image) {
  if (logoBoundsCache.has(image)) return logoBoundsCache.get(image);
  const dimensions = getImageDimensions(image);
  let bounds = { x: 0, y: 0, width: dimensions.width, height: dimensions.height };

  try {
    const sample = document.createElement("canvas");
    sample.width = dimensions.width;
    sample.height = dimensions.height;
    const sampleContext = sample.getContext("2d", { willReadFrequently: true });
    sampleContext.drawImage(image, 0, 0);
    const pixels = sampleContext.getImageData(0, 0, sample.width, sample.height).data;
    let minX = sample.width;
    let minY = sample.height;
    let maxX = -1;
    let maxY = -1;

    for (let y = 0; y < sample.height; y += 1) {
      for (let x = 0; x < sample.width; x += 1) {
        if (pixels[(y * sample.width + x) * 4 + 3] < 12) continue;
        minX = Math.min(minX, x);
        minY = Math.min(minY, y);
        maxX = Math.max(maxX, x);
        maxY = Math.max(maxY, y);
      }
    }

    if (maxX >= minX && maxY >= minY) {
      const padding = Math.max(2, Math.round(Math.max(sample.width, sample.height) * .01));
      const x = Math.max(0, minX - padding);
      const y = Math.max(0, minY - padding);
      bounds = {
        x,
        y,
        width: Math.min(sample.width, maxX + padding + 1) - x,
        height: Math.min(sample.height, maxY + padding + 1) - y
      };
    }
  } catch (error) {
    bounds = { x: 0, y: 0, width: dimensions.width, height: dimensions.height };
  }

  logoBoundsCache.set(image, bounds);
  return bounds;
}

function getLogoPlacement(image, x, y, width, height) {
  const bounds = getLogoBounds(image);
  const scale = Math.min(width / bounds.width, height / bounds.height);
  const drawWidth = bounds.width * scale;
  const drawHeight = bounds.height * scale;
  return {
    bounds,
    x: x + (width - drawWidth) / 2,
    y: y + (height - drawHeight) / 2,
    width: drawWidth,
    height: drawHeight
  };
}

function containLogo(context, image, x, y, width, height) {
  const placement = getLogoPlacement(image, x, y, width, height);
  const bounds = placement.bounds;
  context.drawImage(
    image,
    bounds.x,
    bounds.y,
    bounds.width,
    bounds.height,
    placement.x,
    placement.y,
    placement.width,
    placement.height
  );
}

function roundedRect(context, x, y, width, height, radius) {
  const r = Math.min(radius, width / 2, height / 2);
  context.beginPath();
  context.roundRect(x, y, width, height, r);
}

function addPhotoShade(context, topAlpha = 0, bottomAlpha = .7) {
  const gradient = context.createLinearGradient(0, 0, 0, SIZE);
  gradient.addColorStop(0, `rgba(0,0,0,${topAlpha})`);
  gradient.addColorStop(.52, "rgba(0,0,0,0)");
  gradient.addColorStop(1, `rgba(0,0,0,${bottomAlpha})`);
  context.fillStyle = gradient;
  context.fillRect(0, 0, SIZE, SIZE);
}

function drawPin(context, x, y, scale = 1, color = "#ef1728") {
  context.save();
  context.translate(x, y);
  context.scale(scale, scale);
  context.fillStyle = color;
  context.beginPath();
  context.moveTo(0, 31);
  context.bezierCurveTo(-5, 21, -20, 7, -20, -7);
  context.arc(0, -7, 20, Math.PI, 0);
  context.bezierCurveTo(20, 7, 5, 21, 0, 31);
  context.closePath();
  context.fill();
  context.fillStyle = "#fff";
  context.beginPath();
  context.arc(0, -7, 7, 0, Math.PI * 2);
  context.fill();
  context.restore();
}

function drawAddressBlock(context, x, y, options = {}) {
  const color = options.color || "#fff";
  const size = options.size || 33;
  const lineHeight = options.lineHeight || 38;
  drawPin(context, x + 18, y + 36, options.pinScale || 1, options.pinColor || "#ef1728");
  context.fillStyle = color;
  context.font = `800 ${size}px Arial, sans-serif`;
  context.textBaseline = "top";
  ADDRESS_LINES.forEach((line, index) => context.fillText(line, x + 64, y + index * lineHeight));
}

function drawLogo(context, x, y, width, height, options = {}) {
  if (!state.logo) return;
  const paddingX = Math.max(6, width * .035);
  const paddingY = Math.max(5, height * .045);
  const drawX = x + paddingX;
  const drawY = y + paddingY;
  const drawWidth = width - paddingX * 2;
  const drawHeight = height - paddingY * 2;
  containLogo(context, state.logo, drawX, drawY, drawWidth, drawHeight);
}

function drawName(context, text, x, y, options = {}) {
  if (!text) return;
  const align = options.align || "left";
  const maxWidth = options.maxWidth || 780;
  context.save();
  context.textAlign = align;
  context.textBaseline = "alphabetic";
  context.font = `800 ${options.size || 52}px Arial, sans-serif`;
  context.fillStyle = options.color || "#fff";
  let display = text.toUpperCase();
  while (context.measureText(display).width > maxWidth && display.length > 4) display = `${display.slice(0, -2).trim()}…`;
  context.fillText(display, x, y);
  context.restore();
}

function getPanelPalette(templateKey) {
  const isLight = state.panelStyles[templateKey] === "light";
  return {
    panel: isLight ? "#ffffff" : "#151515",
    panelSoft: isLight ? "rgba(255,255,255,.94)" : "rgba(17,17,17,.86)",
    transparent: isLight ? "rgba(255,255,255,0)" : "rgba(15,15,15,0)",
    text: isLight ? "#151515" : "#ffffff",
    muted: isLight ? "rgba(21,21,21,.65)" : "rgba(255,255,255,.72)",
    quiet: isLight ? "rgba(21,21,21,.12)" : "rgba(255,255,255,.13)"
  };
}

function renderClassic() {
  const context = getContext(canvases.classic);
  context.clearRect(0, 0, SIZE, SIZE);
  if (!state.photo) return;
  coverImage(context, state.photo);
  const topShade = context.createLinearGradient(0, 0, 0, 270);
  topShade.addColorStop(0, "rgba(0,0,0,.62)");
  topShade.addColorStop(1, "rgba(0,0,0,0)");
  context.fillStyle = topShade;
  context.fillRect(0, 0, SIZE, 300);
  addPhotoShade(context, 0, .65);
  drawAddressBlock(context, 48, 44, { size: 30, lineHeight: 35, pinScale: .95 });
  drawLogo(context, 770, 38, 260, 170);
  const name = nameInput.value.trim();
  if (name) {
    context.fillStyle = "#e31726";
    context.fillRect(48, 887, 92, 8);
    drawName(context, name, 48, 968, { size: 58, maxWidth: 940 });
  }
}

function renderCourtside() {
  const context = getContext(canvases.courtside);
  context.clearRect(0, 0, SIZE, SIZE);
  if (!state.photo) return;
  const palette = getPanelPalette("courtside");
  coverImage(context, state.photo, 0, 0, SIZE, 820);
  const gradient = context.createLinearGradient(0, 705, 0, 835);
  gradient.addColorStop(0, palette.transparent);
  gradient.addColorStop(1, palette.panel);
  context.fillStyle = gradient;
  context.fillRect(0, 690, SIZE, 150);
  context.fillStyle = palette.panel;
  context.fillRect(0, 815, SIZE, 265);
  context.fillStyle = "#e31726";
  context.fillRect(0, 815, SIZE, 13);
  context.save();
  context.beginPath();
  context.moveTo(805, 815);
  context.lineTo(1080, 815);
  context.lineTo(1080, 1080);
  context.lineTo(710, 1080);
  context.closePath();
  context.fillStyle = "#e31726";
  context.globalAlpha = .92;
  context.fill();
  context.restore();
  const name = nameInput.value.trim();
  drawName(context, name || "RALLY DINK CENTRAL", 48, 912, { size: name ? 54 : 42, maxWidth: 660, color: palette.text });
  context.fillStyle = palette.muted;
  context.font = "700 22px Arial, sans-serif";
  context.fillText(ADDRESS_SINGLE, 48, 969);
  drawLogo(context, 777, 849, 255, 183, { scrim: false });
}

function renderSpotlight() {
  const context = getContext(canvases.spotlight);
  context.clearRect(0, 0, SIZE, SIZE);
  if (!state.photo) return;
  const palette = getPanelPalette("spotlight");
  coverImage(context, state.photo, 0, 0, 755, SIZE);
  context.fillStyle = palette.panel;
  context.fillRect(755, 0, 325, SIZE);
  context.fillStyle = "#e31726";
  context.beginPath();
  context.moveTo(722, 0);
  context.lineTo(775, 0);
  context.lineTo(775, SIZE);
  context.lineTo(722, SIZE);
  context.lineTo(755, 785);
  context.lineTo(755, 280);
  context.closePath();
  context.fill();
  drawLogo(context, 796, 55, 245, 185, { scrim: false });
  context.save();
  context.translate(916, 490);
  context.rotate(-Math.PI / 2);
  context.textAlign = "center";
  context.fillStyle = palette.quiet;
  context.font = "900 74px Arial, sans-serif";
  context.fillText("RALLY DINK", 0, 0);
  context.restore();
  drawPin(context, 806, 855, .75);
  context.fillStyle = palette.text;
  context.font = "800 16px Arial, sans-serif";
  ADDRESS_LINES.forEach((line, index) => context.fillText(line, 837, 838 + index * 27));
  const name = nameInput.value.trim();
  if (name) {
    context.fillStyle = "rgba(0,0,0,.74)";
    roundedRect(context, 38, 884, 665, 134, 12);
    context.fill();
    drawName(context, name, 69, 970, { size: 52, maxWidth: 595 });
  }
}

