  context.strokeStyle = "rgba(255,255,255,.82)";
  context.strokeRect(49, 49, SIZE - 98, SIZE - 98);
  context.fillStyle = "#e31726";
  context.beginPath();
  context.moveTo(24, 24);
  context.lineTo(410, 24);
  context.lineTo(350, 112);
  context.lineTo(24, 112);
  context.closePath();
  context.fill();
  context.fillStyle = "#fff";
