function wrapText(context, text, maxWidth) {
  const paragraphs = text.split(/\n+/).filter(Boolean);
  const lines = [];
  paragraphs.forEach((paragraph, paragraphIndex) => {
    const words = paragraph.trim().split(/\s+/);
    let line = "";
    words.forEach((word) => {
      const trial = line ? `${line} ${word}` : word;
      if (context.measureText(trial).width > maxWidth && line) {
        lines.push(line);
        line = word;
      } else {
        line = trial;
      }
    });
    if (line) lines.push(line);
    if (paragraphIndex < paragraphs.length - 1) lines.push("");
  });
  return lines;
}

function hexToRgb(hex) {
  const value = hex.replace("#", "");
  return {
    r: parseInt(value.slice(0, 2), 16),
    g: parseInt(value.slice(2, 4), 16),
    b: parseInt(value.slice(4, 6), 16)
  };
}

function renderMessage() {
  const context = getContext(canvases.message);
  context.clearRect(0, 0, SIZE, SIZE);
  if (!state.photo) return;
  coverImage(context, state.photo);
  const rgb = hexToRgb(overlayColor.value);
  context.fillStyle = `rgba(${rgb.r},${rgb.g},${rgb.b},${Number(overlayOpacity.value) / 100})`;
  context.fillRect(0, 0, SIZE, SIZE);
  const lightness = (rgb.r * 299 + rgb.g * 587 + rgb.b * 114) / 1000;
  const textColor = lightness > 155 && Number(overlayOpacity.value) > 60 ? "#151515" : "#fff";
  context.fillStyle = "#e31726";
  context.fillRect(70, 63, 98, 9);
  drawLogo(context, 790, 43, 225, 150);
  const message = messageInput.value.trim() || "Add text to create your text-focused post.";
  let fontSize = message.length > 230 ? 43 : message.length > 140 ? 50 : message.length > 75 ? 59 : 70;
  context.font = `700 ${fontSize}px Georgia, serif`;
  let lines = wrapText(context, message, 865);
  while (lines.length * fontSize * 1.22 > 585 && fontSize > 35) {
    fontSize -= 2;
    context.font = `700 ${fontSize}px Georgia, serif`;
    lines = wrapText(context, message, 865);
  }
  const name = nameInput.value.trim();
  const lineHeight = fontSize * 1.22;
  const totalHeight = lines.length * lineHeight;
  let y = (name ? 560 : 510) - totalHeight / 2;
  context.fillStyle = textColor;
  context.textAlign = "center";
  context.textBaseline = "middle";
  if (name) {
    context.font = "800 27px Arial, sans-serif";
    context.letterSpacing = "1px";
    context.fillText(name.toUpperCase(), SIZE / 2, Math.max(205, y - 45));
    context.letterSpacing = "0px";
    context.font = `700 ${fontSize}px Georgia, serif`;
  }
  lines.forEach((line) => {
    context.fillText(line, SIZE / 2, y + lineHeight / 2);
    y += lineHeight;
  });
  context.textAlign = "left";
  context.fillStyle = textColor;
  context.globalAlpha = .78;
  context.font = "700 19px Arial, sans-serif";
  context.fillText(ADDRESS_SINGLE, 70, 1000);
  context.globalAlpha = 1;
}

function getTextLayoutStyle() {
  const rgb = hexToRgb(overlayColor.value);
  const opacity = Number(overlayOpacity.value) / 100;
  const lightness = (rgb.r * 299 + rgb.g * 587 + rgb.b * 114) / 1000;
  return {
    rgb,
    opacity,
    textColor: lightness > 155 && opacity > .6 ? "#151515" : "#fff",
    solidTextColor: lightness > 155 ? "#151515" : "#fff"
  };
}

