function setReady(isReady) {
  photoTemplateGrid.classList.toggle("has-image", isReady);
  textTemplateGrid.classList.toggle("has-image", isReady);
  downloadButtons.forEach((button) => { button.disabled = !isReady; });
  photoAdjust.hidden = !isReady;
}

function clampPosition(value) {
  return Math.min(1, Math.max(0, value));
}

function updatePositionPreview() {
  positionPreviewImage.style.objectPosition = `${state.photoPosition.x * 100}% ${state.photoPosition.y * 100}%`;
}

function setPhotoPosition(x, y, shouldRender = true) {
  state.photoPosition.x = clampPosition(x);
  state.photoPosition.y = clampPosition(y);
  updatePositionPreview();
  if (shouldRender) renderAll();
}

function movePhoto(direction) {
  const step = .055;
  const movement = {
    left: [step, 0],
    right: [-step, 0],
    up: [0, step],
    down: [0, -step]
  }[direction];
  if (!movement) return;
  setPhotoPosition(state.photoPosition.x + movement[0], state.photoPosition.y + movement[1]);
}

function setTemplatePanelStyle(templateKey, style) {
  state.panelStyles[templateKey] = style;
  document.querySelectorAll(`.template-panel-options[data-template-panel="${templateKey}"] .template-panel-button`).forEach((button) => {
    const isActive = button.dataset.panelStyle === style;
    button.classList.toggle("is-active", isActive);
    button.setAttribute("aria-pressed", String(isActive));
  });

  const renderers = {
    courtside: renderCourtside,
    spotlight: renderSpotlight,
    corner: renderCorner,
    lowerThird: renderLowerThird,
    studio: renderStudio,
    sideRail: renderSideRail,
    scoreboard: renderScoreboard,
    centerline: renderCenterline
  };
  renderers[templateKey]();
}

function setPreviewStyle(style) {
  document.documentElement.dataset.previewStyle = style;
  previewStyleButtons.forEach((button) => {
    const isActive = button.dataset.previewStyle === style;
    button.classList.toggle("is-active", isActive);
    button.setAttribute("aria-pressed", String(isActive));
  });
}

function setMode(mode) {
  state.mode = mode;
  const isText = mode === "text";
  modeTabs.forEach((tab) => {
    const isActive = tab.dataset.mode === mode;
    tab.classList.toggle("is-active", isActive);
    tab.setAttribute("aria-selected", String(isActive));
  });
  photoResults.hidden = isText;
  textResults.hidden = !isText;
  textOptions.hidden = !isText;
  detailsTitle.textContent = isText ? "Add your text" : "Add a name";
  detailsHelp.textContent = isText ? "Set the message and its overlay" : "Optional, leave blank if not needed";
  nameFieldLabel.textContent = isText ? "Name or heading" : "Name or title";
}

function loadFile(file) {
  if (!file || !["image/jpeg", "image/png", "image/webp"].includes(file.type)) return;
  const reader = new FileReader();
  reader.addEventListener("load", () => {
    const image = new Image();
    image.addEventListener("load", () => {
      state.photo = image;
      state.photoPosition = { x: .5, y: .5 };
      state.fileStem = file.name.replace(/\.[^.]+$/, "").replace(/[^a-z0-9]+/gi, "-").replace(/^-|-$/g, "") || "rdc-post";
      positionPreviewImage.src = reader.result;
      updatePositionPreview();
      fileName.textContent = file.name;
      dropZone.classList.add("has-file");
      dropZone.querySelector(".drop-title").textContent = "Photo ready";
      dropZone.querySelector(".drop-help").textContent = "Click to choose another";
      setReady(true);
      renderAll();
      const activeResults = state.mode === "text" ? textResults : photoResults;
      activeResults.scrollIntoView({ behavior: "smooth", block: "start" });
    });
    image.src = reader.result;
  });
  reader.readAsDataURL(file);
}

function downloadCanvas(canvas, templateName) {
  try {
    const link = document.createElement("a");
    link.download = `${state.fileStem}-${templateName}.jpg`;
    link.href = canvas.toDataURL("image/jpeg", .94);
    link.hidden = true;
    document.body.appendChild(link);
    link.click();
    link.remove();
  } catch (error) {
    window.alert("This image could not be downloaded. Please reload the page and try again.");
  }
}

imageInput.addEventListener("change", () => loadFile(imageInput.files[0]));

["dragenter", "dragover"].forEach((eventName) => dropZone.addEventListener(eventName, (event) => {
  event.preventDefault();
  dropZone.classList.add("is-dragging");
}));

["dragleave", "drop"].forEach((eventName) => dropZone.addEventListener(eventName, (event) => {
  event.preventDefault();
  dropZone.classList.remove("is-dragging");
}));

dropZone.addEventListener("drop", (event) => loadFile(event.dataTransfer.files[0]));

modeTabs.forEach((tab) => tab.addEventListener("click", () => setMode(tab.dataset.mode)));

previewStyleButtons.forEach((button) => button.addEventListener("click", () => {
  setPreviewStyle(button.dataset.previewStyle);
}));

document.querySelectorAll(".template-panel-button").forEach((button) => button.addEventListener("click", () => {
  const options = button.closest(".template-panel-options");
  setTemplatePanelStyle(options.dataset.templatePanel, button.dataset.panelStyle);
}));

let positionDrag = null;

positionPreview.addEventListener("pointerdown", (event) => {
  if (!state.photo) return;
  positionDrag = {
    pointerId: event.pointerId,
    startX: event.clientX,
    startY: event.clientY,
    photoX: state.photoPosition.x,
    photoY: state.photoPosition.y
  };
  positionPreview.setPointerCapture(event.pointerId);
  positionPreview.classList.add("is-dragging");
});

positionPreview.addEventListener("pointermove", (event) => {
  if (!positionDrag || positionDrag.pointerId !== event.pointerId) return;
  const bounds = positionPreview.getBoundingClientRect();
  const nextX = positionDrag.photoX - (event.clientX - positionDrag.startX) / bounds.width;
  const nextY = positionDrag.photoY - (event.clientY - positionDrag.startY) / bounds.height;
  setPhotoPosition(nextX, nextY, false);
});

function finishPositionDrag(event) {
  if (!positionDrag || positionDrag.pointerId !== event.pointerId) return;
  positionDrag = null;
  positionPreview.classList.remove("is-dragging");
  renderAll();
}

positionPreview.addEventListener("pointerup", finishPositionDrag);
positionPreview.addEventListener("pointercancel", finishPositionDrag);

positionPreview.addEventListener("keydown", (event) => {
  const directions = { ArrowLeft: "left", ArrowRight: "right", ArrowUp: "up", ArrowDown: "down" };
  const direction = directions[event.key];
  if (!direction) return;
  event.preventDefault();
  movePhoto(direction);
});

positionNudgeButtons.forEach((button) => button.addEventListener("click", () => {
  movePhoto(button.dataset.positionNudge);
}));

positionReset.addEventListener("click", () => setPhotoPosition(.5, .5));

nameInput.addEventListener("input", () => {
  nameCount.textContent = nameInput.value.length;
  renderAll();
});

messageInput.addEventListener("input", () => {
  messageCount.textContent = messageInput.value.length;
  renderTextLayouts();
});

overlayColor.addEventListener("input", () => {
  colorValue.textContent = overlayColor.value.toUpperCase();
  renderTextLayouts();
});

overlayOpacity.addEventListener("input", () => {
  opacityValue.textContent = `${overlayOpacity.value}%`;
  renderTextLayouts();
});

downloadButtons.forEach((button) => button.addEventListener("click", () => {
  downloadCanvas(document.querySelector(`#${button.dataset.canvas}`), button.dataset.name);
}));

window.addEventListener("scroll", () => {
  backToTop.classList.toggle("is-visible", window.scrollY > 700);
}, { passive: true });

backToTop.addEventListener("click", () => {
  window.scrollTo({ top: 0, behavior: "smooth" });
});

setMode("photo");
setPreviewStyle("default");
setReady(false);
